-- Line 3 inspection plans, imported from the plant's IJP workbooks
-- (OneDrive_1_9-21-2026.zip: 33 equipment folders, 282 sheets).
--
-- Shape follows line 1 exactly: one MAIN part per machine, one activity per IJP
-- sheet, and the sheet's Phase/S-Phase checks flattened into standard_checklist
-- as "<group>: <check>" labels.
--
-- requires_shutdown is read straight off the IJP naming — FLIR/FLMRI run on a
-- live plant, FLIS/FLMSI/SIS/SPMSI need the machine stopped. That flag is what
-- feeds the weekly PM report, which had nothing for line 3 before this.
--
-- ijp_phrase is scaffolding: the same check line appears in up to 167 plans, so
-- the distinct text is loaded once and the activities reference it by id. The
-- table is dropped at the end; nothing depends on it afterwards.
--
-- Held back deliberately: seven folders (K11.04, K12.04, K13.05, K13.08,
-- K13.13.14, L54.04, L56.04) name equipment the line-3 master data does not
-- have, so their plans are not imported rather than attached to a guess.

create table if not exists public.ijp_phrase (id int primary key, text text not null);

on conflict (id) do nothing;

-- Safe to re-run: activity codes are unique per part.
  equipment_part_id, activity_code, activity_name, inspection_category,
  frequency_type, custom_interval_days, priority, responsible_role,
  requires_shutdown, instructions, standard_checklist, start_date
)
select
  (select ep.equipment_part_id from public.equipment_parts ep
     join public.equipment e on e.equipment_id = ep.equipment_id
    where e.equipment_code = v.eq and ep.part_code = 'MAIN'),
  v.code, v.name, v.cat::inspection_category, v.freq::frequency_type, v.custom::int,
  v.prio::priority_level, 'Mechanical Engineer', v.shutdown, v.instructions,
  (select coalesce(jsonb_agg(jsonb_build_object('label', p.text) order by o.ord), '[]'::jsonb)
     from unnest(v.ids::int[]) with ordinality o(id, ord)
     join public.ijp_phrase p on p.id = o.id),
  current_date
from (values
